fn solve(input: Vec<char>) -> Vec<char> {
    // Map a digit character to its "good count"
    fn good_count(d: char) -> u32 {
        match d {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => 0, // won't happen for valid input
        }
    }

    // Read the first two characters (guaranteed to be digits).
    let first = input[0];
    let second = input[1];

    // Compute the product of their good counts.
    let product = good_count(first) * good_count(second);

    // Convert to decimal string, collect chars, append newline.
    let mut output: Vec<char> = product.to_string().chars().collect();
    output.push('\n');
    output
}

