        // '1' -> 7, '2' -> 2, product = 14
        let inp: Vec<char> = "12\n".chars().collect();
        assert_eq!(solve(inp), "14\n".chars().collect::<Vec<_>>());

        // '9' -> 2, '8' -> 1, product = 2
        let inp: Vec<char> = "98xyz".chars().collect();
        assert_eq!(solve(inp), "2\n".chars().collect::<Vec<_>>());

        // '0' -> 2, '0' -> 2, product = 4
